const fs = require('fs');

// tests/npm/tty_reset.py runs this on a PTY with TOV_TTY_TEST naming the way it ends.
module.exports = function () {
  const mode = process.env.TOV_TTY_TEST;
  process.stdout.setResetOnExit('<RESET>');
  if (mode === 'cleared') process.stdout.setResetOnExit('');
  process.stdout.write('before\n');
  if (mode === 'process-exit') process.exit(3);
  if (mode === 'uncaught') throw new Error('boom');
  if (mode === 'signal') {
    process.stdin.setRawMode(true);
    fs.writeSync(1, 'READY\n');
    // Busy: the default SIGTERM ends it from the signal handler.
    for (let i = 0; i < 1e12; i++) {}
  }
  return mode === 'trap';
};
